import{_ as o,o as d,c as t,ae as c}from"./chunks/framework.YL6nI5ZP.js";const m=JSON.parse('{"title":"The Network Data Model","description":"","frontmatter":{},"headers":[],"relativePath":"reference/04-network-data-model.md","filePath":"reference/04-network-data-model.md"}'),a={name:"reference/04-network-data-model.md"};function r(s,e,n,i,l,p){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="the-network-data-model" tabindex="-1">The Network Data Model <a class="header-anchor" href="#the-network-data-model" aria-label="Permalink to &quot;The Network Data Model&quot;">​</a></h1><p><code>class Network</code> (<code>network.js:101</code>), one instance <code>window.Net</code>. It is the canonical store for everything the user builds.</p><h2 id="element-shapes" tabindex="-1">Element shapes <a class="header-anchor" href="#element-shapes" aria-label="Permalink to &quot;Element shapes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Collection</th><th>Shape</th></tr></thead><tbody><tr><td><code>nodes[]</code></td><td><code>{ id, type, lngLat:[lng,lat], props }</code></td></tr><tr><td><code>links[]</code></td><td><code>{ id, type, from, to, vertices[], props }</code> (<code>vertices</code> = intermediate coordinates)</td></tr><tr><td><code>subcatchments[]</code></td><td><code>{ id, ring:[[lng,lat]…], props }</code></td></tr><tr><td><code>mesh2D[]</code></td><td><code>{ id:&#39;M2D_n&#39;, ring, manningN, parentSubcatch, props }</code> — derived from the indexed mesh</td></tr><tr><td><code>mesh2DIndexed</code></td><td>Triangle-engine output; see the 2D mesh data model</td></tr><tr><td><code>timeseries</code></td><td><code>{ TS1: [{date,time,value}…] }</code></td></tr><tr><td><code>options</code>, <code>units</code></td><td>Simulation options, <code>&#39;SI&#39;</code>/<code>&#39;US&#39;</code></td></tr><tr><td>Metadata</td><td><code>title</code>, <code>counters</code>, <code>rawSections</code>, <code>curves</code>, <code>lidControls</code>, <code>pollutants</code>, <code>landUses</code>, <code>treatments</code>, <code>aquifers</code>, <code>snowpacks</code>, <code>importedLayers</code></td></tr></tbody></table><h2 id="default-properties" tabindex="-1">Default properties <a class="header-anchor" href="#default-properties" aria-label="Permalink to &quot;Default properties&quot;">​</a></h2><p><strong>Default props</strong> come from factories: <code>defaultNodeProps(type)</code>, <code>defaultLinkProps(type)</code>, <code>defaultSubcatchProps()</code> (<code>network.js:30-54</code>). E.g. JUNCTION <code>{invertEl, maxDepth:2, initDepth, surDepth, aponded}</code>; CONDUIT <code>{roughness:0.013, autoLength:true, xShape:&#39;CIRCULAR&#39;, geom1:1.0, barrels:1}</code>.</p><h2 id="ids-indexes-geojson-cache" tabindex="-1">IDs, indexes, GeoJSON cache <a class="header-anchor" href="#ids-indexes-geojson-cache" aria-label="Permalink to &quot;IDs, indexes, GeoJSON cache&quot;">​</a></h2><ul><li><strong>ID generation</strong> (<code>nextId</code>, <code>network.js:171-181</code>): per-type counters with prefixes from <code>ID_PREFIX</code> (<code>network.js:19-23</code>): <code>J/O/ST/D/RG</code> nodes, <code>C/P/W/OR/OL</code> links, <code>S</code> subcatchments, <code>M2D_</code> mesh cells.</li><li><strong>O(1) lookup:</strong> <code>_nodeMap/_linkMap/_subMap</code> rebuilt by <code>rebuildIndexes()</code> (<code>network.js:141-150</code>); <code>findAny(id)</code> (<code>network.js:197-212</code>) also resolves mesh cells.</li><li><strong>GeoJSON caches:</strong> <code>nodesGeoJSON/linksGeoJSON/subcatchmentsGeoJSON/mesh2DGeoJSON</code> (<code>network.js:784-865</code>) invalidated by <code>_invalidateGeo()</code>; node moves patch in place (<code>_patchGeoForMove</code>, <code>network.js:350-365</code>) so drags don&#39;t rebuild everything.</li></ul><h2 id="undo-redo-command-pattern" tabindex="-1">Undo/redo (command pattern) <a class="header-anchor" href="#undo-redo-command-pattern" aria-label="Permalink to &quot;Undo/redo (command pattern)&quot;">​</a></h2><ul><li>History is an array of <code>{t:&#39;snap&#39;, json}</code> full snapshots and <code>{t:&#39;cmd&#39;, op}</code> deltas. <code>HISTORY_LIMIT=100</code>, snapshots forced every 25 ops (<code>network.js:25-26</code>).</li><li><code>_record(op)</code> (<code>network.js:534-544</code>) logs deltas; <code>commit()</code> (<code>network.js:524-532</code>) pushes a snapshot (used after bulk ops like clear/merge).</li><li>Op types (<code>_applyOp</code>, <code>network.js:636-674</code>): <code>add</code>, <code>del</code> (cascade to connected links, restore outlet/gage refs), <code>move</code>, <code>props</code>, <code>rename</code>, <code>units</code>.</li><li><code>undo/redo</code> (<code>network.js:565-586</code>); <code>_trimHistory</code> (<code>network.js:546-560</code>) drops oldest entries; <code>canUndo/canRedo</code> drive toolbar button states.</li></ul><h2 id="mutations" tabindex="-1">Mutations <a class="header-anchor" href="#mutations" aria-label="Permalink to &quot;Mutations&quot;">​</a></h2><p><code>addNode</code> (<code>226-240</code>), <code>addLink</code> (<code>242-258</code>, auto-computes conduit length), <code>addSubcatchment</code> (<code>260-284</code>, auto-computes area in ha/ac and picks nearest hydraulic node as outlet), <code>moveNode/commitMove</code> (<code>318-336</code>), <code>updateProps</code> (<code>367-382</code>), <code>renameElement</code> (<code>384-393</code>), <code>deleteElements</code> (<code>414-451</code>), <code>setUnits</code> (<code>453-462</code>). Every mutation emits <code>Net.emit()</code> → <code>Net.onChange</code> subscribers re-render (<code>app.js:632-640</code>).</p><h2 id="serialization" tabindex="-1">Serialization <a class="header-anchor" href="#serialization" aria-label="Permalink to &quot;Serialization&quot;">​</a></h2><p><code>serialize()</code> (<code>network.js:465-488</code>) is the canonical model dump (version 2); <code>loadState()</code> (<code>network.js:490-520</code>) restores it, rebuilding indexes and the indexed mesh. <code>rawSections</code> (verbatim INP text from imports) is preserved so that data the UI has no editor for survives round-trips.</p>',14)])])}const u=o(a,[["render",r]]);export{m as __pageData,u as default};
